DELIMITER $$
CREATE TRIGGER tr_sc_insert BEFORE INSERT ON SC
FOR EACH ROW
BEGIN
  IF NEW.Grade < 0 THEN
    SET NEW.Grade = 0;
  ELSEIF NEW.Grade > 100 THEN
    SET NEW.Grade = 100;
  END IF;
END $$
